INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (195, 1, '--network none', '`docker run --network none alpine` 컨테이너 안에서 `/proc/net/dev` 의 네트워크 장치를 보면 기본 실행과 어떻게 다를까요?', '외부와 이어지는 인터페이스가 있는지 봐요.', NULL, NULL, '[]', 'choice', '["`--network none` 도 `eth0` 가 있다", "기본 실행에는 `lo` 만 있다", "`--network none` 은 루프백 `lo` 만 있고 `eth0` 가 없다. 기본(`bridge`)으로 실행하면 `eth0` 와 `lo` 가 보인다", "`--network none` 은 `lo` 도 없다"]', 2, '`docker inspect` 의 `HostConfig.NetworkMode` 는 각각 `none`, `bridge`, `host` 로 저장됩니다.', NULL, NULL, NULL, NULL),
  (195, 2, 'host 네트워크와 -p', '`--network host` 로 실행하면서 `-p 8080:80` 도 쓰면 어떻게 될까요? 없는 네트워크 이름을 `--network` 에 쓰면요?', '호스트 네트워크는 포트를 따로 공개하지 않아요.', NULL, NULL, '[]', 'choice', '["`-p` 가 적용되어 8080 포트가 공개된다", "`WARNING: Published ports are discarded when using host network mode` 경고가 나오고 `-p` 는 무시된다. 없는 네트워크는 `network 이름 not found` 오류로 컨테이너가 만들어지지 않는다", "`--network host` 와 `-p` 는 함께 쓰면 즉시 오류로 종료된다", "없는 네트워크 이름은 `bridge` 로 자동 대체된다"]', 1, '`host` 네트워크는 컨테이너가 호스트의 네트워크를 그대로 씁니다.', NULL, NULL, NULL, NULL),
  (195, 3, '--hostname 과 --domainname', '`--hostname web1` 로 실행한 컨테이너에서 `hostname` 은 무엇일까요? `--domainname ex.local` 도 쓰면 `hostname -f` 는요?', '컨테이너 안에서 보이는 이름을 정해요.', NULL, NULL, '[]', 'choice', '["`hostname` 은 `web1` 이고 `/etc/hosts` 에도 `web1` 이 들어간다. `--domainname ex.local` 을 함께 쓰면 `hostname -f` 가 `web1.ex.local` 이 된다", "`hostname` 은 컨테이너 이름이 된다", "`--hostname` 은 `/etc/hosts` 를 바꾸지 않는다", "`hostname -f` 는 항상 `web1` 만 출력한다"]', 0, '`--hostname` 을 쓰지 않으면 호스트 이름이 짧은 컨테이너 ID 가 됩니다.', NULL, NULL, NULL, NULL),
  (195, 4, 'DNS 검색 설정', '`--dns-search corp.local` 과 `--dns-option ndots:3` 으로 실행하면 컨테이너의 `/etc/resolv.conf` 에 무엇이 생길까요? `--add-host bad` 처럼 형식이 틀리면요?', 'resolv.conf 의 search 와 options 줄이에요.', NULL, NULL, '[]', 'choice', '["두 옵션은 `/etc/hosts` 에만 영향을 준다", "`--add-host bad` 는 이름만으로 정상 등록된다", "`--dns-option` 은 `search` 줄을 만든다", "`search corp.local` 줄과 `options ndots:3` 줄이 생긴다. `--add-host` 는 `이름:주소` 형식이어야 해서 `bad` 는 `bad format for add-host` 오류가 난다"]', 3, '`--add-host 이름:주소` 는 `/etc/hosts` 에 항목을 추가합니다.', NULL, NULL, NULL, NULL),
  (195, 5, '--volumes-from', '`docker run --volumes-from 데이터컨테이너` 로 실행한 컨테이너는 데이터 컨테이너의 `/data` 를 어떻게 볼까요? `:ro` 를 붙이면요?', '볼륨을 그대로 공유해요.', NULL, NULL, '[]', 'choice', '["파일이 복사되어 서로 영향을 주지 않는다", "`:ro` 를 붙여도 쓰기가 가능하다", "데이터 컨테이너가 마운트한 볼륨을 같은 경로에서 그대로 읽고 쓴다(`shared` 파일이 보임). `:ro` 를 붙이면 쓰기가 `Read-only file system` 으로 막힌다. 시작하지 않고 `docker create` 만 한 컨테이너의 볼륨도 쓸 수 있고, 없는 컨테이너는 `No such container` 오류이다", "실행 중인 컨테이너만 지정할 수 있다"]', 2, '볼륨을 컨테이너 사이에 공유하는 방법 중 하나입니다.', NULL, NULL, NULL, NULL),
  (195, 6, '--shm-size', '기본 컨테이너의 `/dev/shm` 크기는 얼마일까요? `--shm-size 128m` 을 쓰면요?', '공유 메모리 크기예요.', NULL, NULL, '[]', 'choice', '["기본은 `1G` 이다", "기본은 `64M`(`df -h /dev/shm` 에서 `64.0M`)이고 `--shm-size 128m` 을 쓰면 `128.0M` 이 된다", "`--shm-size` 는 `/tmp` 크기를 바꾼다", "`--shm-size` 를 써도 크기는 그대로이다"]', 1, '브라우저처럼 공유 메모리를 많이 쓰는 프로그램에서 늘려 씁니다.', NULL, NULL, NULL, NULL),
  (195, 7, '--cpus 와 --cpuset-cpus', '`--cpus 0.5` 로 실행한 컨테이너의 `/sys/fs/cgroup/cpu.max` 는 무엇일까요? `--cpuset-cpus 0` 은요?', 'CPU 시간 할당량과 사용할 코어를 정해요.', NULL, NULL, '[]', 'choice', '["`cpu.max` 는 `50000 100000` 으로 보인다 (100000 마이크로초 주기 중 50000 을 쓸 수 있음). `--cpuset-cpus 0` 은 0번 코어만 쓰게 해서 `cpuset.cpus.effective` 가 `0` 이다", "`cpu.max` 는 `0.5` 로 보인다", "`--cpus 0.5` 는 코어 0.5개만 보이게 한다", "`--cpuset-cpus 0` 은 CPU 시간 비율을 0 으로 만든다"]', 0, '`--cpu-shares 512` 는 `docker inspect` 의 `HostConfig.CpuShares` 에 `512` 로 저장됩니다.', NULL, NULL, NULL, NULL),
  (195, 8, 'memory-reservation', '`--memory 200m --memory-reservation 100m` 은 `docker inspect` 에 어떻게 저장될까요? `--memory 200m --memory-reservation 300m` 은요?', '소프트 한도는 하드 한도보다 작아야 해요.', NULL, NULL, '[]', 'choice', '["예약이 한도보다 커도 정상 실행된다", "`MemoryReservation` 은 저장되지 않는다", "`--memory-reservation` 은 하드 한도이다", "`Memory` 는 209715200, `MemoryReservation` 은 104857600 으로 저장된다. 예약이 한도보다 크면 `Minimum memory limit can not be less than memory reservation limit` 오류가 난다"]', 3, '`--memory` 는 하드 한도, `--memory-reservation` 은 메모리가 부족할 때의 소프트 한도입니다.', NULL, NULL, NULL, NULL),
  (195, 9, '--user 와 --group-add', '`--user 1234:5678`, `--user 1234`, `--user nouser` 로 `id` 를 실행하면 각각 어떻게 될까요? `--group-add 77` 은요?', 'UID 와 GID 를 정해요.', NULL, NULL, '[]', 'choice', '["`--user 1234` 는 `gid=1234` 가 된다", "`--user nouser` 는 새 사용자를 자동으로 만든다", "`1234:5678` 은 `uid=1234 gid=5678`, `1234` 만 쓰면 `gid=0(root)`, 이미지에 없는 이름 `nouser` 는 `unable to find user nouser` 오류이다. `--group-add 77` 은 보조 그룹에 `77` 을 추가한다", "`--group-add` 는 기본 그룹을 바꾼다"]', 2, '이미지에 있는 `nobody` 는 `id -u` 가 `65534` 입니다.', NULL, NULL, NULL, NULL),
  (195, 10, '-w 로 작업 폴더 정하기', '`docker run -w /tmp/x/y alpine pwd` 에서 `/tmp/x/y` 가 이미지에 없으면 어떻게 될까요?', '없는 경로도 만들어 줘요.', NULL, NULL, '[]', 'choice', '["경로가 없으면 오류로 실행되지 않는다", "경로가 없으면 만들어지고 `pwd` 는 `/tmp/x/y` 를 출력한다. `--workdir` 는 같은 옵션의 긴 이름이다", "경로가 없으면 `/` 에서 실행된다", "`-w` 는 이미지의 `WORKDIR` 을 영구히 바꾼다"]', 1, '`WORKDIR` 은 Dockerfile 의 지시어이고 `-w` 는 실행할 때의 지정입니다.', NULL, NULL, NULL, NULL),
  (195, 11, '-e 에 값을 안 쓰면', '`docker run -e B alpine` 처럼 값 없이 변수 이름만 쓰면 컨테이너의 `B` 는 무엇일까요? 호스트에 `B=fromhost` 가 있을 때는요?', '호스트 환경에서 가져와요.', NULL, NULL, '[]', 'choice', '["호스트에 `B` 가 없으면 컨테이너에도 설정되지 않고(`unset`), 호스트에 `B=fromhost` 가 있으면 그 값 `fromhost` 가 전달된다. 값에 공백이 있으면 `-e ''A=a b''` 처럼 따옴표로 감싼다", "항상 빈 문자열로 설정된다", "호스트에 있어도 전달되지 않는다", "`B` 가 없으면 `docker run` 이 오류로 실패한다"]', 0, '`-e A=1` 처럼 값을 직접 정하는 것이 가장 분명한 방법입니다.', NULL, NULL, NULL, NULL),
  (195, 12, '--env-file 형식', '`X=1`, 주석 `# comment`, `Y=two words`, 값 없는 `Z` 가 든 파일을 `--env-file` 로 주면 컨테이너에서 각각 어떻게 될까요? `-e X=cli` 를 함께 쓰면요?', '주석은 무시되고 명령줄이 우선해요.', NULL, NULL, '[]', 'choice', '["주석 줄도 환경 변수로 들어간다", "파일의 `X=1` 이 `-e X=cli` 를 이긴다", "공백이 든 값은 첫 단어만 들어간다", "`X=1`, `Y=two words` 가 설정되고 `#` 로 시작하는 줄은 무시되며 값 없는 `Z` 는 호스트에 없으면 설정되지 않는다. `-e X=cli` 를 함께 쓰면 `X` 는 `cli` 이다. 없는 파일은 `--env-file: open ...: no such file or directory` 오류이다"]', 3, '비밀 값이 든 파일은 저장소에 올리지 않습니다.', NULL, NULL, NULL, NULL),
  (195, 13, 'docker logs 옵션', '5줄을 출력한 컨테이너에서 `docker logs --tail 2`, `--tail 0`, `-t`, `--since 1h` 는 각각 무엇을 보여 줄까요?', '마지막 몇 줄, 시각, 기간 필터예요.', NULL, NULL, '[]', 'choice', '["`--tail 0` 은 전체 로그를 보여 준다", "`-t` 는 로그를 시간 순으로 정렬한다", "`--tail 2` 는 마지막 2줄(`line4 line5`), `--tail 0` 은 아무 줄도 보여 주지 않고, `-t` 는 각 줄 앞에 연도로 시작하는 시각(`2026-...` 형태)을 붙이며, `--since 1h` 는 최근 1시간의 로그(5줄)를 보여 준다. 표준 출력과 표준 오류는 구분되어 `2>/dev/null` 이면 표준 출력만 남는다", "`--since 1h` 는 1시간보다 오래된 로그만 보여 준다"]', 2, '`--until 1h` 는 1시간 이전의 로그만 보여 주므로 방금 시작한 컨테이너에서는 아무것도 나오지 않습니다.', NULL, NULL, NULL, NULL),
  (195, 14, 'docker inspect --type', '컨테이너 이름 `web` 에 `docker inspect --type container web` 과 `docker inspect --type image web` 을 하면 각각 어떻게 될까요?', '찾을 종류를 정해서 조회해요.', NULL, NULL, '[]', 'choice', '["`--type image` 도 컨테이너 정보를 보여 준다", "`--type container` 는 그 컨테이너의 정보를 보여 주고 `--type image` 는 이미지 중에서만 찾으므로 컨테이너 이름은 찾지 못해 빈 결과 `[]` 가 나온다", "`--type container` 는 이미지 정보를 보여 준다", "`--type` 은 출력 형식을 JSON 으로 바꾼다"]', 1, '같은 이름의 컨테이너와 이미지가 있을 때 `--type` 으로 종류를 정해 조회할 수 있습니다.', NULL, NULL, NULL, NULL),
  (195, 15, '네트워크 끊기', '컨테이너에 `lo` 만 있고 외부 네트워크가 없게 하는 `--network` 값을 채우세요.', '"없음"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["none", "off", "null", "isolated"]', NULL, '`bridge` 가 기본값입니다.', '[0]', 'docker run --network {0} alpine true', NULL, NULL),
  (195, 16, '컨테이너 호스트 이름', '컨테이너 안의 호스트 이름을 `web1` 로 정하는 옵션을 채우세요.', '"호스트 이름"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--hostname", "--host", "--name", "--node"]', NULL, '`/etc/hosts` 에도 이 이름이 들어갑니다.', '[0]', 'docker run {0} web1 alpine hostname', NULL, NULL),
  (195, 17, '볼륨 공유', '다른 컨테이너가 마운트한 볼륨을 그대로 쓰게 하는 옵션을 채우세요.', '"볼륨들을 ~에서"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--volumes-from", "--share-volume", "--mount-from", "--link-volume"]', NULL, '끝에 `:ro` 를 붙이면 읽기 전용입니다.', '[0]', 'docker run --rm {0} data alpine ls /data', NULL, NULL),
  (195, 18, '공유 메모리 크기', '`/dev/shm` 의 크기를 128MB 로 정하는 옵션을 채우세요.', '"shm" 과 "size" 를 이은 이름이에요.', NULL, NULL, '[]', 'fill', '["--shm-size", "--shm", "--tmp-size", "--mem-shared"]', NULL, '기본값은 64MB 입니다.', '[0]', 'docker run {0} 128m alpine true', NULL, NULL),
  (195, 19, 'CPU 사용 한도', '컨테이너가 쓸 CPU 를 0.5코어로 제한하는 옵션을 채우세요.', '"CPU 들"이라는 뜻의 이름이에요.', NULL, NULL, '[]', 'fill', '["--cpus", "--cpu-limit", "--cores", "--cpu-max"]', NULL, '`cpu.max` 가 `50000 100000` 이 됩니다.', '[0]', 'docker run {0} 0.5 alpine true', NULL, NULL),
  (195, 20, '소프트 메모리 한도', '메모리가 부족할 때 적용되는 소프트 한도를 정하는 옵션을 채우세요.', '"메모리 예약"이라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--memory-reservation", "--memory-soft", "--memory-min", "--memory-guard"]', NULL, '이 값은 `--memory` 보다 작아야 합니다.', '[0]', 'docker run --memory 200m {0} 100m alpine true', NULL, NULL),
  (195, 21, '보조 그룹 추가', '컨테이너 프로세스에 보조 그룹 77 을 추가하는 옵션을 채우세요.', '"그룹 추가"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--group-add", "--user-group", "--gid-add", "--groups"]', NULL, '`--user` 는 기본 UID 와 GID 를 정합니다.', '[0]', 'docker run {0} 77 alpine id -G', NULL, NULL),
  (195, 22, '실행할 때의 작업 폴더', '컨테이너 안에서 실행 폴더를 `/etc` 로 정하는 긴 옵션을 채우세요.', '"작업 폴더"라는 뜻의 영어 단어 조합이에요.', NULL, NULL, '[]', 'fill', '["--workdir", "--cwd", "--chdir", "--dir"]', NULL, '짧게는 `-w` 로 씁니다.', '[0]', 'docker run {0} /etc alpine pwd', NULL, NULL),
  (195, 23, '환경 변수 파일', '파일의 `이름=값` 줄을 환경 변수로 넣는 옵션을 채우세요.', '"환경 변수 파일"이라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--env-file", "--envs", "--env-from", "--vars"]', NULL, '`#` 로 시작하는 줄은 주석으로 무시됩니다.', '[0]', 'docker run {0} app.env alpine env', NULL, NULL),
  (195, 24, '마지막 몇 줄만', '`docker logs` 에서 마지막 2줄만 보는 옵션을 채우세요.', '"꼬리"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--tail", "--last", "--head", "--end"]', NULL, '`-n 2` 로 줄여 쓸 수 있습니다.', '[0]', 'docker logs {0} 2 web', NULL, NULL),
  (195, 25, '컨테이너 크기 보기', '`docker ps` 에 각 컨테이너의 크기 열을 추가하는 옵션을 채우세요.', '"size" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-s", "-z", "-k", "-m"]', NULL, '`SIZE` 열에 `virtual` 이 포함된 값이 나옵니다.', '[0]', 'docker ps {0}', NULL, NULL),
  (195, 26, '데이터 컨테이너로 볼륨 공유하기', '볼륨을 컨테이너 사이에 공유하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 쓰기 → 공유 → 읽기 전용 확인 순서예요.', NULL, NULL, '[]', 'order', '["`docker volume create data-vol` 로 볼륨을 만든다", "`docker run -d --name data -v data-vol:/data alpine sh -c ''echo shared > /data/f; sleep 60''` 로 파일을 쓰는 컨테이너를 실행한다", "`docker run --rm --volumes-from data alpine cat /data/f` 로 `shared` 가 읽히는지 본다", "`docker run --rm --volumes-from data:ro alpine sh -c ''echo x > /data/g''` 가 `Read-only file system` 으로 막히는지 본다"]', NULL, '끝나면 `docker rm -f data` 와 `docker volume rm data-vol` 로 정리합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (195, 27, '환경 변수 파일로 실행하기', '파일의 환경 변수를 넣고 명령줄 값이 우선하는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '파일 작성 → 실행 → 덮어쓰기 → 오류 순서예요.', NULL, NULL, '[]', 'order', '["`app.env` 에 `X=1`, `# comment`, `Y=two words` 를 쓴다", "`docker run --rm --env-file app.env alpine env` 로 `X=1` 과 `Y=two words` 가 들어갔는지 본다", "`docker run --rm --env-file app.env -e X=cli alpine sh -c ''echo $X''` 로 `cli` 가 출력되는지 본다", "없는 파일 이름을 주면 `no such file or directory` 오류가 나는지 본다"]', NULL, '`#` 줄은 환경 변수로 들어가지 않습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (195, 28, '네트워크가 없는 컨테이너 점검하기', '네트워크를 끊은 컨테이너의 상태를 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '실행 → 장치 확인 → 비교 → 저장값 확인 순서예요.', NULL, NULL, '[]', 'order', '["`docker run --rm --network none alpine cat /proc/net/dev` 로 장치를 본다", "`lo` 만 있고 `eth0` 가 없는지 확인한다", "`--network` 없이 실행해 `eth0` 와 `lo` 가 보이는지 비교한다", "`docker inspect` 의 `HostConfig.NetworkMode` 가 `none` 인지 확인한다"]', NULL, '`--network host` 에서는 `-p` 가 무시되고 경고가 나옵니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (195, 29, '로그 줄여 읽기', '많은 로그에서 필요한 부분을 읽는 순서입니다. 순서에 맞게 놓아 보세요.', '전체 크기 → 끝부분 → 시각 → 스트림 분리 순서예요.', NULL, NULL, '[]', 'order', '["`docker logs web | wc -l` 로 전체 줄 수를 센다", "`docker logs --tail 2 web` 으로 마지막 2줄만 본다", "`docker logs -t --tail 2 web` 으로 각 줄의 시각을 함께 본다", "`docker logs web 2>&1 >/dev/null` 로 표준 오류 로그만 본다"]', NULL, '`docker logs web 2>/dev/null` 은 표준 출력만 보여 줍니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
